package oauth
import("net/url";"testing")
func TestLexOpenDriveManagementNativeAuthorizationScopesStayExact(t *testing.T){for _,scope:=range []string{"https://www.googleapis.com/auth/drive","https://www.googleapis.com/auth/drive.readonly","https://www.googleapis.com/auth/drive.metadata.readonly"}{s:=&memStore{provider:"google",kind:"google-workspace",id:"fixture",secret:"fixture-secret",settings:map[string]string{"oauth_lexopen_persistent":"v1","oauth_scopes":scope}};m:=New(s);start,e:=m.Start("account","http://127.0.0.1:3400/v1/oauth/callback");u,parseErr:=url.Parse(start);if e!=nil||parseErr!=nil||u.Query().Get("scope")!=scope||u.Query().Get("client_secret")!=""{t.Fatal("native start failed")};app,_:=s.OAuthApp("account");p:=lexopenDriveProvider(Providers["google"],app);if len(p.Scopes)!=1||p.Scopes[0]!=scope{t.Fatal("native provider requested upstream Mail/Calendar scopes")}}}
